/** OpenCode Zen free tier: official keyless gateway used by OpenCode itself (`Authorization: Bearer public`). Models and limits come from the live /zen/v1/models response. */
PROVIDERS.splice(1, 0, {
  id: "opencodezen", name: "OpenCode Zen", tagline: "", speed: "~90 tok/s", color: "#1f8a70", icon: "terminal",
  contextWindow: 200000,
  models: Object.entries(CTX_VERIFIED.opencodezen ?? {}).map(([id, v]) => ({
    id, label: (v.name ?? id).replace(/\s+Free$/i, ""), reasoning: !!v.reasoning, vision: !!v.vision, contextWindow: v.ctx, maxOutput: Math.min(v.out ?? 16384, 32768),
  })),
});

/* Overlay real limits from live /models responses; strip hand-typed "NNk ctx" claims from notes (the picker shows the real number). */
for (const p of PROVIDERS) {
  for (const m of p.models) {
    const v = CTX_VERIFIED[p.id]?.[m.id];
    if (v) {
      m.contextWindow = v.ctx; m.verified = true;
      if (v.out) m.maxOutput = Math.min(v.out, 32768);
      if (v.vision !== undefined) m.vision = v.vision;
    }
    if (m.note) m.note = m.note.replace(/^[\d.,]+\s?[kKM]?\s*ctx\s*·\s*/, "");
    if (m.contextWindow && m.maxOutput && m.maxOutput > m.contextWindow / 2) m.maxOutput = Math.floor(m.contextWindow / 2);
  }
}

export const DEMO_PROVIDER: ProviderMeta = {
  id: "demo", name: "OpenDesign Templates", tagline: "", speed: "instant", color: "#868e96", icon: "draw",
  models: [{ id: "zeus-templates", label: "Template designer", note: "Used when the native engine is unavailable", vision: false }],
};

export const EFFORTS: { id: "low" | "medium" | "high" | "max"; label: string; desc: string }[] = [
  { id: "low", label: "Low", desc: "Fastest, minimal thinking" },
  { id: "medium", label: "Medium", desc: "Balanced" },
  { id: "high", label: "High", desc: "Deeper design reasoning" },
  { id: "max", label: "Max", desc: "Think as long as needed" },
];

export function findProvider(id: string): ProviderMeta {
  return PROVIDERS.find((p) => p.id === id) ?? DEMO_PROVIDER;
}

/** Returns true ONLY when the active provider + model supports image/file attachments. */
export function supportsAttachments(providerId: string, modelId: string): boolean {
  if (providerId.startsWith("custom:")) return true;
  const prov = findProvider(providerId);
  const model = prov.models.find((m) => m.id === modelId) ?? prov.models[0];
  return !!model?.vision;
}

export type Effort = "low" | "medium" | "high" | "max";

export const EFFORT_ORDER: Effort[] = ["low", "medium", "high", "max"];

const FLAGSHIP = /ultra|-pro\b|\bpro\b|opus|fable|kimi-k2|glm-5|qwen3-235b|mistral-large-4|step-5|beam|k2-horizon|gemini-3\.1|gpt-oss-120b|sonnet|big-pickle|minimax-m2|deepseek-v4-pro|longcat|qwen4|grok-4/i;
const SMALL = /(^|[^\d])(0\.\d|1|1\.\d|2|3|4|e2b|e4b)b\b|lite|lightning|bolt|nano|mini|tiny|flash-lite|fast|instant|moondream|smol|230m|500m/i;

/** Reasoning tiers a model really honours. Empty when the model does not reason. */
export function reasoningTiers(model?: ModelInfo | null): Effort[] {
  if (!model?.reasoning) return [];
  const id = `${model.id} ${model.label}`;
  if (FLAGSHIP.test(id)) return ["low", "medium", "high", "max"];
  if (SMALL.test(id)) return ["low", "medium"];
  return ["low", "medium", "high"];
}

export function clampEffort(effort: Effort, tiers: Effort[]): Effort {
  if (!tiers.length || tiers.includes(effort)) return effort;
  const want = EFFORT_ORDER.indexOf(effort);
  return [...tiers].sort((a, b) => Math.abs(EFFORT_ORDER.indexOf(a) - want) - Math.abs(EFFORT_ORDER.indexOf(b) - want))[0] ?? effort;
}

export function fmtCtx(n?: number, verified?: boolean): string {
  if (!n) return "";
  const v = n >= 1_000_000 ? `${+(n / 1_048_576).toFixed(n % 1_048_576 === 0 || n === 1_000_000 ? 0 : 1)}M` : `${Math.round(n / 1000)}k`;
  return verified ? v : `~${v}`;
}

export function currentModel(providerId: string, modelId: string): { provider: ProviderMeta; model?: ModelInfo | undefined } {
  const provider = findProvider(providerId);
  return { provider, model: provider.models.find((m) => m.id === modelId) };
}

// Browser-Mode Custom & Keyless Gateway Streaming Fallback
// Extracted from engine.ts to keep core agent orchestration modular and concise.

export interface ZeusAttachment { name: string; mime: string; dataUrl: string; }
export interface ZeusChatMessage { role: "user" | "assistant" | "system"; content: string; attachments?: ZeusAttachment[]; }
export interface ZeusCustomEndpoint { baseUrl: string; apiKey: string; format: "openai" | "anthropic"; }
export interface ChatRequest { requestId: string; provider: string; model: string; effort: string; system: string; messages: ZeusChatMessage[]; workspaceRoot?: string; custom?: ZeusCustomEndpoint; }

